using System;using System.Linq;using System.Reflection;using System.Text.Json;using System.IO;using MotorwaysSim;
namespace MotorwaysSim {public sealed partial class TrafficWorld {public void TopologyAt(double at){if(ActiveCars!=0)throw new Exception("Unexpected traffic in topology-only check");Time=at;FinishRemovals();}}}
class DirectTopology {static void Main(string[] a){var opt=new JsonSerializerOptions{IncludeFields=true,PropertyNameCaseInsensitive=true};var d=JsonSerializer.Deserialize<CustomScenarioDefinition>(File.ReadAllText(a[0]),opt);var s=new CustomScenarioSession(d);var apply=typeof(CustomScenarioSession).GetMethod("Apply",BindingFlags.NonPublic|BindingFlags.Instance);var checkpoints=new System.Collections.Generic.List<object>();int[] targets={90,170,240,280,290,300,320,430,480,535,540,570,590,620,650,660,690,710,720,740,760,790,810,820,830,840,850,860,870,880,890};int target=0;int index=s.CompletedEvents;var clock=System.Diagnostics.Stopwatch.StartNew();try{for(;index<d.events.Length;index++){if(clock.Elapsed.TotalSeconds>30)throw new Exception("30s direct event-only topology diagnostic cap");var e=d.events[index];while(target<targets.Length&&e.videoTime>targets[target]){checkpoints.Add(new{video=targets[target++],stock=s.World.Inventory[0]});}s.World.TopologyAt(e.at);if(!(bool)apply.Invoke(s,new object[]{e}))throw new Exception(e.kind+" source"+e.videoTime+": "+s.World.LastAction);s.World.TopologyAt(e.at);}Console.WriteLine(JsonSerializer.Serialize(new{mode="DIRECT_EVENT_TOPOLOGY_ONLY_NO_PHYSICS_NO_SCORE",events=index,total=d.events.Length,checkpoints,inventory=s.World.Inventory,wall=clock.Elapsed.TotalSeconds},opt));}catch(Exception e){Console.WriteLine(JsonSerializer.Serialize(new{mode="DIRECT_EVENT_TOPOLOGY_ONLY_NO_PHYSICS_NO_SCORE",events=index,total=d.events.Length,checkpoints,error=e.Message,at=d.events[index].at,video=d.events[index].videoTime,inventory=s.World.Inventory},opt));Environment.ExitCode=1;}}}
